/* 0093_counting_a_niche_without_downloading_one.sql, flattened for the Supabase SQL editor. Generated by scripts/flatten-migration.mjs - do not edit this file, edit the migration and run the script again. One statement per line, no line comments, nothing to lose to a newline. The commentary lives in the migration itself. */
create or replace function public.niche_page_counts() returns table (niche text, listings bigint) language sql stable security definer set search_path = public as $$ select n.slug, count(distinct m.id) from public.marketplace_listings m cross join lateral ( select m.niche as slug where m.niche is not null union select unnest(m.secondary_niches) as slug ) n where m.status = 'active' group by n.slug; $$;
comment on function public.niche_page_counts() is 'Active listings per niche, counting primary and secondary - the rule a niche page shows. Replaces reading every listing to count them.';
revoke all on function public.niche_page_counts() from public, anon, authenticated;
grant execute on function public.niche_page_counts() to service_role;
